// 캐시를 붙이기 전, 코드보다 먼저 이 세 줄을 적는다:
① 열쇠   무엇 단위로?  예: product:{id}:{lang}  (권한 다르면 권한도)
② 수명   TTL 얼마나?   예: 300초 (이 데이터는 5분 낡아도 OK)
③ 무효화 언제 지우나?  예: 상품 수정 시 product:{id}:* 삭제

// 이 셋을 못 적으면 캐시를 넣을 준비가 안 된 것

async function getUser(id) {
  const hit = await cache.get(`user:${id}`);
  if (hit) return JSON.parse(hit);           // hit: 그대로
  const user = await db.getUser(id);          // miss: DB 에서
  await cache.set(`user:${id}`, JSON.stringify(user), 'EX', 300);  // 채움(TTL)
  return user;
}
async function updateUser(id, data) {
  await db.updateUser(id, data);
  await cache.del(`user:${id}`);              // 무효화(삭제 → 다음 조회에 새로)
}

// ① TTL 지터: 만료 시각을 흩뜨린다
const ttl = 300 + Math.floor(Math.random() * 60);

// ② 락: 하나만 DB 를 채우고 나머지는 기다림(single-flight)
//    miss 시 락 획득한 하나만 DB 조회, 나머지는 그 결과 대기

